  function shuffle(a) { var result=a.slice();for(var index=result.length-1;index>0;index--){var swapIndex=Math.floor(Math.random()*(index+1)),value=result[index];result[index]=result[swapIndex];result[swapIndex]=value;}return result; }
  function lastRoleForSeat(history,playerId){var value=history[playerId];return Array.isArray(value)?value[value.length-1]:value;}
  function campTrailForSeat(history,playerId){var value=history[playerId];return Array.isArray(value)?value:(value?[value]:[]);}
  function specialTrailForSeat(history,playerId){var value=history[playerId];return Array.isArray(value)?value:(value?[value]:[]);}
  function dealRolesWithHistoryGuards(roleKeys,players,roleHistory,specialRoleHistory,evilHistory,roleRerollEnabled,specialRoleRerollEnabled,evilTripleGuardEnabled){if(!roleRerollEnabled&&!specialRoleRerollEnabled&&!evilTripleGuardEnabled)return shuffle(roleKeys);var previousRoles=players.map(function(player){return lastRoleForSeat(roleHistory,player.id);}),specialTrails=players.map(function(player){return specialTrailForSeat(specialRoleHistory,player.id);}),evilTrails=players.map(function(player){return specialTrailForSeat(evilHistory,player.id);}),remaining=shuffle(roleKeys),dealt=Array(players.length);function isSpecial(role){return role!=='忠臣';}function dealSeat(seatIndex){if(seatIndex===players.length)return true;var specialTrail=specialTrails[seatIndex],evilTrail=evilTrails[seatIndex],candidates=shuffle(remaining).filter(function(role,index,roles){var repeatedSpecial=specialRoleRerollEnabled&&specialTrail.length>=2&&specialTrail[specialTrail.length-2]&&specialTrail[specialTrail.length-1]&&isSpecial(role),repeatedEvil=evilTripleGuardEnabled&&evilTrail.length>=2&&evilTrail[evilTrail.length-2]&&evilTrail[evilTrail.length-1]&&meta[role][0]==='evil';return (!roleRerollEnabled||role!==previousRoles[seatIndex])&&!repeatedSpecial&&!repeatedEvil&&roles.indexOf(role)===index;});return candidates.some(function(role){var roleIndex=remaining.indexOf(role);remaining.splice(roleIndex,1);dealt[seatIndex]=role;if(dealSeat(seatIndex+1))return true;remaining.splice(roleIndex,0,role);return false;});}return dealSeat(0)?dealt:shuffle(roleKeys);}
  function hero() { return '<header class="hero"><span class="eyebrow">THE ROUND TABLE</span><div class="title-row"><i>♔</i><h1>阿瓦隆</h1><i>♔</i></div><span class="subtitle">圆桌之下，忠诚与谎言同时苏醒</span></header>'; }
  function roundInfoText() { var captain=S.players.find(function(player){return player.id===(S.firstCaptainId||1);})||S.players[0],direction=S.speakingDirection||'顺时针';return '首车长：'+esc(captain?captain.name:'')+' · '+direction; }
