  function rows(roles, camp) { var unique = []; roles.filter(function(r){ return meta[r][0] === camp; }).forEach(function(r){ var x=unique.find(function(q){return q.name===r;}); x ? x.count++ : unique.push({name:r,count:1}); });if(camp==='evil'){var order=['莫甘娜','刺客','爪牙','奥伯伦','莫德雷德'];unique.sort(function(a,b){return order.indexOf(a.name)-order.indexOf(b.name);});}return unique.map(function(r){ var d=meta[r.name]; return '<button class="role-card '+camp+'" data-role="'+r.name+'"><span>'+d[1]+'</span><b>'+r.name+(r.count>1 ? '<em>×'+r.count+'</em>':'')+'</b><small>'+ (camp==='good'?'好人阵营':'邪恶阵营') +'</small></button>'; }).join(''); }
