  function bindSetup() { document.getElementById('minus').onclick=function(){S.count=Math.max(5,S.count-1);makePlayers();settings();}; document.getElementById('plus').onclick=function(){S.count=Math.min(15,S.count+1);makePlayers();settings();};  document.getElementById('gear').onclick=function(){S.options=!S.options;settings();}; document.getElementById('start').onclick=start; document.querySelectorAll('.setup-seats .seat').forEach(function(b){b.onclick=function(){var p=S.players[+b.dataset.seat-1],n=prompt('设置 '+p.name+' 的昵称',p.name);if(n&&n.trim()){p.name=n.trim().slice(0,10);settings();}};}); document.querySelectorAll('[data-role]').forEach(function(b){b.onclick=function(){showRole(b.dataset.role);};}); if(S.options){document.getElementById('phoneOn').onclick=function(){S.phone=true;settings();};document.getElementById('phoneOff').onclick=function(){S.phone=false;settings();};if(S.count===9){document.getElementById('evilThree').onclick=function(){S.nineEvilCount=3;S.fourthFail=1;settings();};document.getElementById('evilFour').onclick=function(){S.nineEvilCount=4;S.fourthFail=2;settings();};}(document.getElementById('failOne')||{}).onclick=function(){S.fourthFail=1;settings();};(document.getElementById('failTwo')||{}).onclick=function(){S.fourthFail=2;settings();};document.querySelectorAll('[data-time]').forEach(function(b){b.onclick=function(){S.assassinMinutes=Math.max(1,Math.min(10,S.assassinMinutes+(+b.dataset.time)));settings();};});} bindModal(); }
