  function identityPanel() { if(!S.identityOpen) return '<section class="fold" id="identityFold"><span>✦</span><b>查看身份</b><em>展开</em></section>'; if(!S.selected) return '<section class="panel identity-panel"><div class="section-head fold-head" id="identityFold"><span>✦</span> 查看身份 <em>收起</em></div><p class="identity-copy">点击自己的座位，确认身份后可以查看本局角色</p><div class="seats identity-seats">'+S.players.map(function(p){return '<button class="seat '+(S.viewed[p.id]?'viewed':'')+'" data-identity="'+p.id+'">'+avatar(p)+'<span>'+esc(p.name)+'</span></button>';}).join('')+'</div></section>'; var p=S.selected,d=meta[p.role],v=vision(p);return '<section class="panel identity-panel '+p.camp+'"><div class="section-head fold-head" id="identityFold"><span>✦</span> 你的身份信息 <em>收起</em></div><div class="identity-role"><span class="identity-symbol">'+d[1]+'</span><small>'+ (p.camp==='good'?'好人阵营':'邪恶阵营') +'</small><h2>'+p.role+'</h2><div class="ability"><b>'+d[2]+'</b><p>'+d[3]+'</p>'+(v.length?'<div class="intel"><strong>本局情报</strong>'+v.map(function(x){return '<span>'+avatar(x,'tiny')+esc(x.name)+'</span>';}).join('')+'</div>':'')+'</div><small class="identity-countdown">'+S.identitySeconds+' 秒后自动收起</small><button class="gold primary" id="hideIdentity">收起身份</button></div></section>'; }
  function gameRoles() { if(!S.rolesOpen) return '<section class="fold" id="rolesFold"><span>✦</span><b>本局角色卡牌</b><em>展开</em></section>'; return '<section class="role-section game-roles role-count-'+S.count+'"><div class="section-head fold-head" id="rolesFold"><span>✦</span> 本局角色卡牌 <em>收起</em></div><div class="role-grid">'+rows(activeRoleSet(),'good')+'</div><div class="role-grid evil-grid">'+rows(activeRoleSet(),'evil')+'</div></section>'; }
  function questMap() { var route=S.quests.map(function(q){return '<button class="wagon '+q.status+' '+(q.i===S.current+1?'current':'')+'" data-wagon="'+q.i+'"><span class="wagon-top">'+(q.status==='success'?'♛':q.status==='fail'?'💣'.repeat(q.bombs||1):q.i)+'</span><b>'+q.size+' 位骑士</b><small>'+ (q.need>1?'💣💣':'') +'</small><div class="riders">'+q.riders.map(function(id){return avatar(S.players[id-1],'mini-avatar');}).join('')+'</div><em>'+ (q.status==='success'?'任务成功':q.status==='fail'?'任务失败':q.i===S.current+1?'当前关卡':'待远征') +'</em></button>';}).join('');var list='<div class="quest-list">'+S.quests.map(function(q){return '<button class="quest-list-item '+q.status+'" data-wagon="'+q.i+'"><span>'+ (q.status==='success'?'♛':q.status==='fail'?'💣'.repeat(q.bombs||1):q.i) +'</span><b>'+q.size+' 人远征</b><small>'+q.riders.map(function(id){return S.players[id-1].name;}).join(' · ')+'</small><em>'+ (q.status==='success'?'任务成功':q.status==='fail'?'任务失败':q.i===S.current+1?'当前关卡':'待远征') +'</em></button>';}).join('')+'</div>';return '<section class="panel quest-panel"><div class="quest-title"><div class="quest-heading"><b>任务远征</b><small class="quest-round-info">（'+roundInfoText()+'）</small></div><div><button class="view-switch '+(S.questView==='map'?'active':'')+'" data-view="map">地图</button><button class="view-switch '+(S.questView==='list'?'active':'')+'" data-view="list">列表</button><small>第 '+Math.min(S.current+1,5)+' / 5 轮</small></div></div>'+ (S.questView==='map'?'<div class="route">'+route+'</div>':list) +missionControls()+'</section>'; }
  function missionControls() { if(S.result) return ''; if(S.good>=3) return assassination(); if(S.phone&&S.phoneActive) return phoneVote(); var q=S.quests[S.current]; return '<div class="mission-control"><div class="mission-head"><b>第 '+q.i+' 趟车任务</b><small>炸毁需 '+q.need+' 枚炸弹</small></div>'+(S.phone?'<button class="gold primary" id="phoneStart">手机投票</button><div class="divider">亦可手动记录</div>':'')+'<div class="two-actions"><button class="success" data-manual="success">任务成功</button><button class="fail" data-manual="fail">任务失败</button></div></div>'; }
  function phoneVote() { var q=S.quests[S.current],voted=Object.keys(S.phoneVotes).length,all=voted>=q.size,turn=Math.min(voted+1,q.size),voter=S.votingPlayer?S.players[S.votingPlayer-1]:null,body;if(voter)body='<div class="phone-vote-choice"><div class="phone-vote-top"><button id="cancelCurrentVote">取消投票</button><b>任务投票（'+turn+' / '+q.size+'）</b><i></i></div><strong>'+esc(voter.name)+'</strong><small>请选择一张任务牌</small><div class="inline-vote-buttons"><button data-inline-vote="success">任务成功</button><button data-inline-vote="fail">任务失败</button></div></div>';else body='<div class="phone-vote-top"><button id="cancelVote">取消投票</button><b>任务投票（'+turn+' / '+q.size+'）</b><i></i></div><div class="phone-vote-task"><strong>第 '+q.i+' 趟车任务</strong><small>炸毁需 '+q.need+' 枚炸弹</small></div><div class="seats vote-seats phone-vote-seats">'+S.players.map(function(p){return '<button class="seat phone-vote-seat '+(S.phoneVotes[p.id]?'viewed':'')+'" data-voter="'+p.id+'">'+avatar(p)+'<span>'+esc(p.name)+(S.phoneVotes[p.id]?' · 已投票':'')+'</span></button>';}).join('')+'</div><small class="vote-reset-hint">长按已投席位可撤回该次投票</small>'+(all?'<button class="gold primary phone-reveal" id="revealVotes">开票</button>':'');return '<div class="phone-vote mini-phone-vote">'+body+'</div>'; }
  function assassination() { var m=Math.floor(S.assassinSeconds/60),s=S.assassinSeconds%60;return '<section class="assassination mini-assassination"><div class="strike-head"><div><small>THE FINAL STRIKE</small><b>刺杀阶段</b></div><span>☾</span></div><div class="strike-main"><em>好人已完成三次任务</em><strong>刺杀讨论时间</strong><time>'+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+'</time><p>请讨论刺杀目标，确认后将立即揭示最终结果。</p></div><div class="strike-targets"><b>可选刺杀目标</b><div class="targets">'+S.players.filter(function(p){return p.camp==='good';}).map(function(p){return '<button data-kill="'+p.id+'">'+avatar(p)+esc(p.name)+'</button>';}).join('')+'</div></div></section>'; }
  function scheduleIdentity(seconds) { clearInterval(S.identityTimer);S.identitySeconds=seconds;S.identityTimer=setInterval(function(){S.identitySeconds--;if(S.identitySeconds<=0){clearInterval(S.identityTimer);S.selected=null;S.identityOpen=Object.keys(S.viewed).length<S.players.length;S.identitySeconds=0;}game();},1000); }
  function game() { S.page='game'; app.innerHTML=hero()+'<button class="back" id="back">‹</button><main class="game">'+identityPanel()+gameRoles()+questMap()+'</main>'+roleModal(); bindGame(); }
  function bindGame() { document.getElementById('back').onclick=function(){ if(confirm('结束本局游戏？')) {clearInterval(S.identityTimer);clearInterval(S.assassinTimer);settings();}};document.getElementById('identityFold').onclick=function(){clearInterval(S.identityTimer);S.identityOpen=!S.identityOpen;S.selected=null;S.identitySeconds=0;game();};document.getElementById('rolesFold').onclick=function(){S.rolesOpen=!S.rolesOpen;game();};document.querySelectorAll('[data-identity]').forEach(function(b){b.onclick=function(){var p=S.players[+b.dataset.identity-1];if(confirm('你是骑士 '+p.id+'？')){var first=!S.viewed[p.id];S.selected=p;S.viewed[p.id]=true;scheduleIdentity(first?15:5);game();}};});var hide=document.getElementById('hideIdentity');if(hide)hide.onclick=function(){clearInterval(S.identityTimer);S.selected=null;S.identitySeconds=0;game();};document.querySelectorAll('[data-role]').forEach(function(b){b.onclick=function(){showRole(b.dataset.role);};});document.querySelectorAll('[data-manual]').forEach(function(b){b.onclick=function(){mark(b.dataset.manual,1);};});var start=document.getElementById('phoneStart');if(start)start.onclick=function(){S.phoneActive=true;S.identityOpen=false;S.selected=null;clearInterval(S.identityTimer);game();};var cancel=document.getElementById('cancelVote');if(cancel)cancel.onclick=function(){S.phoneActive=false;S.phoneVotes={};game();};document.querySelectorAll('[data-voter]').forEach(function(b){b.onclick=function(){vote(+b.dataset.voter);};});var reveal=document.getElementById('revealVotes');if(reveal)reveal.onclick=function(){var f=Object.keys(S.phoneVotes).filter(function(id){return S.phoneVotes[id]==='fail';}).length;mark(f>=S.quests[S.current].need?'fail':'success',f||1);};document.querySelectorAll('[data-wagon]').forEach(function(b){b.onclick=function(){var q=S.quests[+b.dataset.wagon-1];if(q.status==='fail'){var n=prompt('设置炸弹数量（1 至 '+q.size+'）',q.bombs||1);if(n){q.bombs=Math.max(1,Math.min(q.size,+n||1));game();}};};});document.querySelectorAll('[data-kill]').forEach(function(b){b.onclick=function(){var p=S.players[+b.dataset.kill-1];if(confirm('是否确认刺杀 '+p.name+'？'))finish(p.role==='梅林'?'邪恶阵营胜利':'好人阵营胜利',p.role==='梅林'?'刺杀成功：目标正是梅林。':'刺杀失败：目标并非梅林。');};});bindModal(); }
  function vote(id) { if(S.phoneVotes[id]||Object.keys(S.phoneVotes).length>=S.quests[S.current].size) return; var p=S.players[id-1],modal=document.getElementById('modal');modal.className='modal';modal.innerHTML='<div class="dialog vote-dialog"><span class="dialog-symbol">✦</span><b>任务投票</b><small>请选择一张任务牌</small><div class="vote-buttons"><button data-vote="success">任务成功</button><button data-vote="fail">任务失败</button></div><button class="ghost close">取消投票</button></div>';modal.querySelectorAll('[data-vote]').forEach(function(b){b.onclick=function(){S.phoneVotes[id]=(p.camp==='good'||b.dataset.vote==='success')?'success':'fail';S.quests[S.current].riders.push(id);modal.className='modal hidden';game();};});bindModal(); }
  function startAssassin() { clearInterval(S.assassinTimer);S.assassinSeconds=S.assassinMinutes*60;S.assassinTimer=setInterval(function(){S.assassinSeconds--;if(S.assassinSeconds<=0){clearInterval(S.assassinTimer);finish('好人阵营胜利','刺杀讨论时间结束，刺客未选择刺杀目标。');return;}game();},1000);game(); }
  function advanceAfterMission() { transition('MISSION');S.current++;S.phoneActive=false;S.phoneVotes={};S.phoneTeam=[];if(S.evil>=3)finish('邪恶阵营胜利','邪恶阵营已摧毁三次任务。');else if(S.good>=3)startAssassin();else game(); }
  function mark(status,bombs) { var q=S.quests[S.current],lancelot=S.players.find(function(p){return p.role==='兰斯洛特';});q.status=status;q.bombs=status==='fail'?Math.max(1,bombs):0;if(status==='success')S.good++;else S.evil++;if(lancelot){lancelot.loyalty+=status==='success'?1:-1;if(lancelot.loyalty<=-2&&!lancelot.fallen){lancelot.fallen=true;lancelot.camp='evil';}}if(S.lake.remain>0&&q.i===S.lake.nextMission){openLake();}else advanceAfterMission(); }
  function openLake() { var holder=S.players.find(function(p){return p.id===S.lake.holder;}),choices=S.players.filter(function(p){return p.id!==S.lake.holder&&S.lake.checked.indexOf(p.id)<0;}),modal=document.getElementById('modal');modal.className='modal';modal.innerHTML='<div class="dialog lake-dialog"><span class="dialog-symbol">✺</span><b>湖中审判</b><small>请 <strong>'+esc(holder.name)+'</strong>，选择一名未被查验的玩家</small><div class="lake-targets">'+choices.map(function(p){return '<button data-lake="'+p.id+'">'+avatar(p)+esc(p.name)+'</button>';}).join('')+'</div></div>';modal.querySelectorAll('[data-lake]').forEach(function(b){b.onclick=function(){var target=S.players[+b.dataset.lake-1];S.lake.checked.push(target.id);S.lake.remain--;S.lake.holder=S.lake.remain?target.id:null;S.lake.nextMission++;modal.innerHTML='<div class="dialog lake-dialog"><span class="dialog-symbol">✺</span><b>湖中审判结果</b><strong class="lake-camp '+target.camp+'">'+(target.camp==='good'?'GOOD':'EVIL')+'</strong><small>'+esc(target.name)+' · 仅展示阵营；查验权已转交。</small><button class="gold primary close">收起结果</button></div>';modal.querySelector('.close').onclick=function(){modal.className='modal hidden';advanceAfterMission();};};}); }
  function finish(winner,copy) { clearInterval(S.assassinTimer);clearInterval(S.identityTimer);S.result={winner:winner,copy:copy}; var order=S.players.slice().sort(function(a,b){var goodFirst=winner==='好人阵营胜利';return a.camp===b.camp?a.id-b.id:(a.camp===(goodFirst?'good':'evil')?-1:1);});app.innerHTML=hero()+'<section class="reveal '+(winner==='好人阵营胜利'?'good':'evil')+'"><span>'+ (winner==='好人阵营胜利'?'♛':'☾') +'</span><h2>'+winner+'</h2><p>'+copy+'</p><div class="reveal-list">'+order.map(function(p){return '<div class="reveal-row '+p.camp+'">'+avatar(p)+'<b>'+esc(p.name)+'</b><em>'+p.role+'</em></div>';}).join('')+'</div><button class="gold primary" id="again">再来一把</button></section>';document.getElementById('again').onclick=function(){S.result=null;makePlayers();settings();}; }
  function inputAsk(title, label, initial, type, onConfirm) { var modal=document.getElementById('modal');modal.className='modal';modal.innerHTML='<div class="dialog confirm-dialog input-dialog"><span class="dialog-symbol">✦</span><b>'+esc(title)+'</b><p>'+esc(label)+'</p><input id="dialogInput" value="'+esc(initial)+'" inputmode="'+(type==='number'?'numeric':'text')+'" maxlength="'+(type==='number'?'2':'10')+'"><div class="dialog-actions"><button class="ghost close">取消</button><button class="gold confirm">保存</button></div></div>';var input=modal.querySelector('#dialogInput');setTimeout(function(){input.focus();input.select();},0);modal.querySelector('.close').onclick=function(){modal.className='modal hidden';};modal.querySelector('.confirm').onclick=function(){var value=input.value.trim();if(!value)return;modal.className='modal hidden';onConfirm(value);}; }
  function resultThenMark(status, bombs) { collapsePrivate();var modal=document.getElementById('modal'),failed=status==='fail',count=failed?Math.max(1,bombs||1):0,seconds=failed?5:2,tickTimer,body=failed?'<b>任务失败</b><strong>本车被投 <em class="mission-result-bomb-count">'+count+'</em> 枚炸弹</strong>':'<span class="dialog-symbol">♛</span><b>任务成功</b><strong>本车顺利完成</strong>';modal.className='modal';modal.innerHTML='<div class="dialog mission-result '+status+'">'+body+'<small class="mission-result-countdown">'+seconds+' 秒后自动关闭</small></div>';var countdown=modal.querySelector('.mission-result-countdown'),hide=function(){clearInterval(tickTimer);modal.className='modal hidden';};modal.onclick=function(event){if(event.target===modal)hide();};tickTimer=setInterval(function(){seconds--;if(seconds>0&&countdown)countdown.textContent=seconds+' 秒后自动关闭';},1000);setTimeout(function(){hide();mark(status,count||1);},seconds*1000); }
  function recordManualMission(status) { collapsePrivate();mark(status,1); }
  function beginGame() { if(!S.players.length) makePlayers();if(S.count===9&&S.nineEvilRandom){S.nineEvilCount=Math.random()<.5?3:4;S.fourthFail=S.nineEvilCount===4?2:1;}var roleHistory={},specialRoleHistory={},evilHistory={};try{roleHistory=JSON.parse(localStorage.getItem('avalon-role-history')||'{}');specialRoleHistory=JSON.parse(localStorage.getItem('avalon-special-role-history')||'{}');evilHistory=JSON.parse(localStorage.getItem('avalon-evil-history')||'{}');}catch(e){}var refreshEvilGuard=S.evilTripleGuardGameCount>=3;if(refreshEvilGuard)S.evilTripleGuardEnabled=Math.random()<.5;var deck=dealRolesWithHistoryGuards(activeRoleSet(),S.players,roleHistory,specialRoleHistory,evilHistory,S.consecutiveRoleReroll,S.consecutiveSpecialRoleReroll,S.evilTripleGuardEnabled);S.players.forEach(function(p,i){p.role=deck[i];p.camp=meta[p.role][0];p.loyalty=p.role==='兰斯洛特'?0:null;p.fallen=false;roleHistory[p.id]=p.role;specialRoleHistory[p.id]=specialTrailForSeat(specialRoleHistory,p.id).concat(p.role!=='忠臣').slice(-2);evilHistory[p.id]=specialTrailForSeat(evilHistory,p.id).concat(p.camp==='evil').slice(-2);});try{localStorage.setItem('avalon-role-history',JSON.stringify(roleHistory));localStorage.setItem('avalon-special-role-history',JSON.stringify(specialRoleHistory));localStorage.setItem('avalon-evil-history',JSON.stringify(evilHistory));}catch(e){}S.evilTripleGuardGameCount=refreshEvilGuard?1:S.evilTripleGuardGameCount+1;S.quests=missionSizes[S.count].map(function(n,i){return {i:i+1,size:n,need:i===3?S.fourthFail:missionFails[S.count][i],status:'',bombs:0,riders:[],leaderId:0};});S.current=0;S.good=0;S.evil=0;S.viewed={};S.identityOpen=true;S.rolesOpen=true;S.phoneActive=false;S.phoneVotes={};S.phoneTeam=[];S.phonePlayer=null;clearInterval(S.identityTimer);clearInterval(S.assassinTimer);var lake=S.players.find(function(p){return p.role==='湖中仙女';});S.lake={holder:lake?lake.id:null,checked:[],remain:lake?2:0,pending:false,nextMission:2};game(); }
  function missionSummary(player) { var votes=(S.voteHistory||[]).filter(function(v){return v.playerId===player.id;});if(votes.length)return votes.map(function(v){return player.camp==='good'?'第 '+v.round+' 车':'第 '+v.round+' 车 · '+(v.card==='fail'?'💣':'任务成功');}).join(' · ');var rides=S.quests.map(function(q){return q.riders.indexOf(player.id)>=0?'第 '+q.i+' 车':'';}).filter(Boolean);return rides.length?rides.join(' · '):''; }
  function collapsePrivate() { clearInterval(S.identityTimer);S.identityOpen=false;S.selected=null;S.identitySeconds=0; }
  function skillStatus(player) { if(player.role==='兰斯洛特')return '圣剑试炼 · 忠诚值 '+player.loyalty+(player.fallen?' · 已堕落为邪恶阵营':' · 未堕落');if(S.lake.holder===player.id)return '湖中审判 · 剩余 '+S.lake.remain+' 次 · 已查验 '+S.lake.checked.length+' 人';return ''; }
  function identityPanel() { if(!S.identityOpen) return '<section class="fold" id="identityFold"><span>✦</span><b>查看身份</b><em>展开</em></section>';if(!S.selected)return '<section class="panel identity-panel"><div class="section-head fold-head" id="identityFold"><span>✦</span> 查看身份 <em>收起</em></div><p class="identity-copy">点击自己的座位，确认身份后可以查看本局角色</p><div class="seats identity-seats">'+S.players.map(function(p){return '<button class="seat '+(S.viewed[p.id]?'viewed':'')+'" data-identity="'+p.id+'">'+avatar(p)+'<span>'+esc(p.name)+'</span></button>';}).join('')+'</div></section>';var p=S.selected,d=meta[p.role],v=vision(p),status=skillStatus(p);return '<section class="panel identity-panel '+p.camp+'"><div class="section-head fold-head" id="identityFold"><span>✦</span> 你的身份信息 <em>收起</em></div><div class="identity-role"><span class="identity-symbol">'+d[1]+'</span><small>'+ (p.camp==='good'?'好人阵营':'邪恶阵营') +'</small><h2>'+p.role+'</h2><div class="ability"><b>'+d[2]+'</b><p>'+d[3]+'</p>'+(v.length?'<div class="intel"><strong>本局情报</strong>'+v.map(function(x){return '<span>'+avatar(x,'tiny')+esc(x.name)+'</span>';}).join('')+'</div>':'')+'</div>'+(status?'<div class="skill-state">'+esc(status)+'</div>':'')+'<small class="identity-countdown">'+S.identitySeconds+' 秒后自动收起</small><button class="gold primary" id="hideIdentity">收起身份</button></div></section>'; }
  function vote(id) { if(S.phoneVotes[id]||Object.keys(S.phoneVotes).length>=S.quests[S.current].size)return;S.votingPlayer=id;collapsePrivate();game(); }
  function openLake() { var holder=S.players.find(function(p){return p.id===S.lake.holder;}),choices=S.players.filter(function(p){return p.id!==S.lake.holder&&S.lake.checked.indexOf(p.id)<0;}),modal=document.getElementById('modal');modal.className='modal';modal.innerHTML='<div class="dialog lake-dialog"><span class="dialog-symbol">✺</span><b>湖中审判</b><small>请 <strong>'+esc(holder.name)+'</strong>，选择一名未被查验的玩家</small><div class="lake-targets">'+choices.map(function(p){return '<button data-lake="'+p.id+'">'+avatar(p)+esc(p.name)+'</button>';}).join('')+'</div></div>';modal.querySelectorAll('[data-lake]').forEach(function(b){b.onclick=function(){var target=S.players[+b.dataset.lake-1];S.lake.checked.push(target.id);S.lake.remain--;S.lake.holder=S.lake.remain?target.id:null;S.lake.nextMission++;saveActiveGame();var transfer=S.lake.remain?'仅展示阵营；查验权已转交给该玩家。':'仅展示阵营；湖中审判已结束。';modal.innerHTML='<div class="dialog lake-dialog"><span class="dialog-symbol">✺</span><b>湖中审判结果</b><strong class="lake-camp '+target.camp+'">'+(target.camp==='good'?'GOOD':'EVIL')+'</strong><small>'+esc(target.name)+' · '+transfer+'</small><button class="gold primary close">收起结果</button></div>';modal.querySelector('.close').onclick=function(){modal.className='modal hidden';advanceAfterMission();};};}); }
