    if(target.dataset.identity){var player=S.players[+target.dataset.identity-1];ask('确认身份','你是'+player.name+'？','确定',function(){var first=!S.viewed[player.id];S.selected=player;S.viewed[player.id]=true;scheduleIdentity(first?15:5);game();});return;}
    if(target.dataset.kill){var victim=S.players[+target.dataset.kill-1];if(S.good>=3&&!S.result){askAssassination(victim);return;}ask('最终刺杀','是否确认刺杀 '+victim.name+'？','确认刺杀',function(){finish(victim.role==='梅林'?'邪恶阵营胜利':'好人阵营胜利',victim.role==='梅林'?'刺杀成功：目标正是梅林。':'刺杀失败：目标并非梅林。');});}
