  function bindSetup(){document.getElementById('minus').onclick=function(){S.count=Math.max(5,S.count-1);makePlayers();settings();};document.getElementById('plus').onclick=function(){S.count=Math.min(15,S.count+1);makePlayers();settings();};document.getElementById('gear').onclick=function(){S.options=!S.options;settings();};document.getElementById('start').onclick=function(){S.voteHistory=[];beginGame();window.scrollTo(0,0);};document.querySelectorAll('.setup-seats .seat').forEach(function(button){button.onclick=function(){var player=S.players[+button.dataset.seat-1];inputAsk('设置骑士昵称','请输入 '+player.name+' 的昵称',player.name,'text',function(name){player.name=name.slice(0,10);settings();});};});document.querySelectorAll('[data-role]').forEach(function(button){button.onclick=function(){showRole(button.dataset.role);};});if(S.options){document.getElementById('phoneOn').onclick=function(){S.phone=true;settings();};document.getElementById('phoneOff').onclick=function(){S.phone=false;settings();};(document.getElementById('failOne')||{}).onclick=function(){S.fourthFail=1;settings();};(document.getElementById('failTwo')||{}).onclick=function(){S.fourthFail=2;settings();};document.getElementById('repeatRoleOn').onclick=function(){S.repeatRoleReroll=true;settings();};document.getElementById('repeatRoleOff').onclick=function(){S.repeatRoleReroll=false;settings();};document.getElementById('repeatCampOn').onclick=function(){S.repeatCampReroll=true;try{localStorage.removeItem('avalon-camp-history');}catch(e){}settings();};document.getElementById('repeatCampOff').onclick=function(){S.repeatCampReroll=false;settings();};document.querySelectorAll('[data-time]').forEach(function(button){button.onclick=function(){S.assassinMinutes=Math.max(1,Math.min(10,S.assassinMinutes+(+button.dataset.time)));settings();};});}bindModal();}
