  phoneVote=function(){var quest=S.quests[S.current],voted=Object.keys(S.phoneVotes).length,all=voted>=quest.size,turn=Math.min(voted+1,quest.size),voter=S.votingPlayer?S.players[S.votingPlayer-1]:null,candidates=S.players,body;if(voter)body='<div class="phone-vote-choice"><div class="phone-vote-top"><button id="cancelCurrentVote">取消投票</button><b>任务投票（'+turn+' / '+quest.size+'）</b><i></i></div><strong>'+esc(voter.name)+'</strong><small>请选择一张任务牌</small><div class="inline-vote-buttons"><button data-inline-vote="success">任务成功</button><button data-inline-vote="fail">任务失败</button></div></div>';else body='<div class="phone-vote-top"><button id="cancelVote">取消投票</button><b>任务投票（'+turn+' / '+quest.size+'）</b><i></i></div><div class="phone-vote-task"><strong>第 '+quest.i+' 趟车任务</strong><small>炸毁需 '+quest.need+' 枚炸弹</small></div><div class="seats vote-seats phone-vote-seats">'+candidates.map(function(player){return '<button class="seat phone-vote-seat '+(S.phoneVotes[player.id]?'viewed':'')+'" data-voter="'+player.id+'">'+avatar(player)+'<span>'+esc(player.name)+(S.phoneVotes[player.id]?' · 已投票':'')+'</span></button>';}).join('')+'</div><small class="vote-reset-hint">长按已投席位可撤回该次投票</small>'+(all?'<button class="gold primary phone-reveal" id="revealVotes">开票</button>':'');return '<div class="phone-vote mini-phone-vote">'+body+'</div>';};
